"""Deterministic generator for schemas/transit.sql (SAMULAS-style transit cards).

Like the course's week 3-5 schema (cards / stations / swipes) but bigger, with
card types, fares, a line column and no triggers installed - you write those.
"""
import random
from datetime import datetime, timedelta
from pathlib import Path

random.seed(55)
OUT = Path(__file__).resolve().parent.parent / "schemas" / "transit.sql"

SCHEMA = """\
-- =====================================================================
--  transit.db  -  city transit cards (mock data, generated by src/gen_transit.py)
--  amount_kurus: boarding < 0, topup > 0, refund > 0  (same rule as the course)
--  cards.balance_kurus is consistent with SUM(swipes.amount_kurus) at reset.
--  NO triggers are installed - building them is your job (section 10).
-- =====================================================================
PRAGMA foreign_keys = ON;

CREATE TABLE fares (
    card_type   TEXT PRIMARY KEY,
    fare_kurus  INTEGER NOT NULL CHECK (fare_kurus > 0)
);

CREATE TABLE cards (
    id            INTEGER PRIMARY KEY,
    owner         TEXT NOT NULL,
    card_type     TEXT NOT NULL REFERENCES fares(card_type),
    issued_at     TEXT NOT NULL,
    balance_kurus INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE stations (
    id       INTEGER PRIMARY KEY,
    name     TEXT NOT NULL UNIQUE,
    district TEXT NOT NULL,
    line     TEXT NOT NULL CHECK (line IN ('Tram', 'Bus')),
    closed   INTEGER NOT NULL DEFAULT 0 CHECK (closed IN (0, 1))
);

CREATE TABLE swipes (
    id           INTEGER PRIMARY KEY,
    card_id      INTEGER NOT NULL REFERENCES cards(id),
    station_id   INTEGER REFERENCES stations(id),
    type         TEXT NOT NULL CHECK (type IN ('boarding', 'refund', 'topup')),
    datetime     TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    amount_kurus INTEGER NOT NULL CHECK (typeof(amount_kurus) = 'integer'),
    CHECK (
        (type = 'boarding' AND amount_kurus < 0) OR
        (type = 'refund'   AND amount_kurus > 0) OR
        (type = 'topup'    AND amount_kurus > 0)
    )
);

"""

FARES = [("full", 2000), ("student", 1000), ("teacher", 1500), ("senior", 500)]
STATIONS = [
    ("Gar", "Ilkadim", "Tram"), ("Cumhuriyet Meydani", "Ilkadim", "Tram"), ("Saathane", "Ilkadim", "Tram"),
    ("Pazar", "Ilkadim", "Bus"), ("Atakent", "Atakum", "Tram"), ("Yurtlar", "Atakum", "Tram"),
    ("OMU Rektorluk", "Atakum", "Tram"), ("Universite", "Atakum", "Tram"), ("Cakirlar", "Atakum", "Bus"),
    ("Kurupelit", "Atakum", "Bus"), ("Belediye Evleri", "Tekkekoy", "Bus"), ("Tekkekoy Merkez", "Tekkekoy", "Tram"),
    ("Sanayi", "Tekkekoy", "Bus"), ("Kalkanca", "Canik", "Bus"), ("Canik Merkez", "Canik", "Bus"),
    ("Hastane", "Ilkadim", "Bus"), ("Sahil", "Atakum", "Tram"), ("Stadyum", "Canik", "Tram"),
]
NAMES = ["Ayse Y.", "Mehmet K.", "Fatma D.", "Ahmet S.", "Zeynep C.", "Mustafa Y.", "Elif A.", "Emre O.",
         "Selin A.", "Can D.", "Deniz K.", "Baris E.", "Ece K.", "Burak K.", "Merve O.", "Kerem A.",
         "Irem P.", "Onur T.", "Gizem K.", "Hakan G.", "Esra Y.", "Murat K.", "Seda D.", "Oguz K.",
         "Cem S.", "Derya C.", "Tolga Y.", "Nazli A.", "Ufuk O.", "Pinar A."]


def q(v):
    if v is None:
        return "NULL"
    if isinstance(v, int):
        return str(v)
    return "'" + str(v).replace("'", "''") + "'"


def ins(table, cols, rows):
    return (f"INSERT INTO {table} ({', '.join(cols)}) VALUES\n" +
            ",\n".join("  (" + ", ".join(q(v) for v in r) + ")" for r in rows) + ";\n\n")


def main():
    sql = [SCHEMA, ins("fares", ["card_type", "fare_kurus"], FARES)]
    stations = [(i, n, d, l, 1 if n == "Sanayi" else 0) for i, (n, d, l) in enumerate(STATIONS, 1)]
    sql.append(ins("stations", ["id", "name", "district", "line", "closed"], stations))
    fare = dict(FARES)
    types = random.choices([t for t, _ in FARES], [45, 35, 10, 10], k=len(NAMES))
    cards = []
    swipes = []
    for cid, (owner, ctype) in enumerate(zip(NAMES, types), 1):
        issued = datetime(2026, 9, 1) + timedelta(days=random.randint(0, 25))
        cards.append([cid, owner, ctype, issued.strftime("%Y-%m-%d"), 0])
    # a card that was issued but never used, and one only topped up
    sql_cards_extra = [[31, "Unused Card", "full", "2026-10-15", 0], [32, "Topup Only", "student", "2026-10-02", 0]]
    cards += sql_cards_extra

    home = {c[0]: random.sample(range(1, len(STATIONS) + 1), 2) for c in cards}
    bal = {c[0]: 0 for c in cards}
    events = []
    for c in cards[:30]:
        cid, _, ctype, issued, _ = c
        day = datetime.strptime(issued, "%Y-%m-%d")
        events.append((day + timedelta(hours=7), cid, None, "topup", 10000))
        rides_days = random.random()
        while day < datetime(2026, 10, 31):
            day += timedelta(days=1)
            if random.random() < (0.75 if rides_days > 0.3 else 0.35):
                a, b = home[cid]
                for hour, st in ((random.randint(7, 9), a), (random.randint(16, 19), b)):
                    t = day + timedelta(hours=hour, minutes=random.randint(0, 59), seconds=random.randint(0, 59))
                    events.append((t, cid, st, "boarding", -fare[ctype]))
                    if random.random() < 0.12:   # transfer within an hour
                        st2 = random.randint(1, len(STATIONS))
                        events.append((t + timedelta(minutes=random.randint(10, 50)), cid, st2, "boarding", -fare[ctype]))
    events.append((datetime(2026, 10, 3, 12), 32, None, "topup", 5000))
    events.sort()
    out = []
    for t, cid, st, typ, amt in events:
        if typ == "boarding" and bal[cid] + amt < 0:
            top = random.choice([5000, 10000, 20000])
            out.append((t - timedelta(minutes=2), cid, None, "topup", top))
            bal[cid] += top
        if typ == "boarding" and st == 13 and t > datetime(2026, 10, 20):
            st = 11  # Sanayi closed on 2026-10-20
        out.append((t, cid, st, typ, amt))
        bal[cid] += amt
    # a few refunds (double-charged boardings)
    for i in random.sample([k for k, e in enumerate(out) if e[3] == "boarding"], 6):
        t, cid, st, _, amt = out[i]
        out.append((t + timedelta(minutes=3), cid, st, "refund", -amt))
        bal[cid] += -amt
    out.sort()
    for sid, (t, cid, st, typ, amt) in enumerate(out, 1):
        swipes.append((sid, cid, st, typ, t.strftime("%Y-%m-%d %H:%M:%S"), amt))
    for c in cards:
        c[4] = bal[c[0]]
    sql.append(ins("cards", ["id", "owner", "card_type", "issued_at", "balance_kurus"], cards))
    for k in range(0, len(swipes), 400):
        sql.append(ins("swipes", ["id", "card_id", "station_id", "type", "datetime", "amount_kurus"], swipes[k:k + 400]))
    OUT.write_text("".join(sql))
    print(f"wrote {OUT}: {len(cards)} cards, {len(swipes)} swipes")


if __name__ == "__main__":
    main()
